import "./css/Festval_serch_details.css";

const select_Maker = (e) =>{      
  const idValue = e.target.id;
  if(idValue == "class_ground"){
    alert("지역 셀렉트");    
  }
  else if(idValue == "class_date"){
    alert("월별 셀렉트");
  }
  else{
    alert("잘못된 접근입니다.");
  }
}
const select_Making = () => {
  const hiddenbox = document.getElementById('select_hidden');
}

const Festval_serch_details = () =>{
    return (
        <div className='search_box'>
          <div className='search_class'>           
            <button id='class_ground' onClick={select_Maker} className='select_box'>전국</button>
            <button id='class_date' onClick={select_Maker} className='select_box'>월별</button>                       
            <div id="select_hidden" ref={select_Making}></div>
          </div>          
          <div className='thema_class'>
            <div id="class_thema1" className='thema_box'>계절테마1</div>
            <div id="class_thema2" className='thema_box'>계절테마2</div>
            <div id="" className='thema_box'>계절테마3</div>
            <div id="class_thema4" className='thema_box'>계절테마4</div>
          </div>
        </div>
    );
};

export default Festval_serch_details;
